CREATE TABLE dms_library (id BIGINT AUTO_INCREMENT PRIMARY KEY,code VARCHAR(32) NOT NULL UNIQUE,name VARCHAR(80) NOT NULL,workshop VARCHAR(60) NOT NULL,planned_capacity INT NOT NULL,active BOOLEAN NOT NULL,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL);
CREATE TABLE dms_user (id BIGINT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(32) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,full_name VARCHAR(50) NOT NULL,role VARCHAR(20) NOT NULL,library_code VARCHAR(32),enabled BOOLEAN NOT NULL,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL);
CREATE TABLE dms_document (id BIGINT AUTO_INCREMENT PRIMARY KEY,order_no VARCHAR(32) NOT NULL UNIQUE,product_code VARCHAR(40) NOT NULL,product_name VARCHAR(120) NOT NULL,library_id BIGINT NOT NULL,planned_qty INT NOT NULL,completed_qty INT NOT NULL,defect_qty INT NOT NULL,due_date DATE NOT NULL,status VARCHAR(20) NOT NULL,batch_no VARCHAR(40),created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,CONSTRAINT fk_order_center FOREIGN KEY(library_id) REFERENCES dms_library(id));
CREATE TABLE dms_version_record (id BIGINT AUTO_INCREMENT PRIMARY KEY,document_id BIGINT NOT NULL,operation_name VARCHAR(50) NOT NULL,good_qty INT NOT NULL,defect_qty INT NOT NULL,operator_name VARCHAR(50) NOT NULL,reported_at DATETIME(6) NOT NULL,remark VARCHAR(200),created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,CONSTRAINT fk_report_order FOREIGN KEY(document_id) REFERENCES dms_document(id));
CREATE TABLE dms_approval_task (id BIGINT AUTO_INCREMENT PRIMARY KEY,approval_task_no VARCHAR(32) NOT NULL UNIQUE,document_id BIGINT NOT NULL,approval_task_type VARCHAR(30) NOT NULL,sample_qty INT NOT NULL,defect_qty INT NOT NULL,result VARCHAR(20) NOT NULL,inspector VARCHAR(50),created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,CONSTRAINT fk_inspection_order FOREIGN KEY(document_id) REFERENCES dms_document(id));
CREATE TABLE dms_storage_node (id BIGINT AUTO_INCREMENT PRIMARY KEY,code VARCHAR(32) NOT NULL UNIQUE,name VARCHAR(80) NOT NULL,library_id BIGINT NOT NULL,status VARCHAR(20) NOT NULL,oee INT NOT NULL,last_heartbeat DATETIME(6) NOT NULL,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,CONSTRAINT fk_equipment_center FOREIGN KEY(library_id) REFERENCES dms_library(id));
CREATE INDEX idx_order_status_due ON dms_document(status,due_date); CREATE INDEX idx_report_order_time ON dms_version_record(document_id,reported_at); CREATE INDEX idx_equipment_status ON dms_storage_node(status);
